Definition rd_errinvA (C : rdctxA) (m1 : amem) : Prop :=
  (exists nc, u8arr asegs m1 (a_NC C) (u16s (map (Z_to_bv 64) nc)) /\ length nc = length (a_rt0 C))
  /\ (exists msvw, rw_cells asegs m1 (a_MSVP C) [C4 msvw])
  /\ (exists tlw, rw_cells asegs m1 (a_TLP C) [C4 tlw])
  /\ (exists csA, rw_cells asegs m1 (a_SPA C) csA /\ cells_size csA = 56%nat)
  /\ stk asegs m1 (a_lo C) (a_SPA C)
  /\ munch (rd_WA C) (a_m C) m1 /\ wmono asegs (a_m C) m1 /\ mem_inv asegs m1.

(* [comment removed for export] *)
Definition rd_mainA_errpost (C : rdctxA) (e : Z) : machine_state -> Prop :=
  fun ms' => exists m' (x1 x5 x6 x7 x10 x12 x13 x14 x15 x16 x17 x19 x20 x21 x22 x23 x24 x27 x28 x29 x30 x31 : word),
    ms' = MS (mkR x1 (Z_to_bv 64 (a_SPA C)) (a_gp C) (a_tp C) x5 x6 x7 (Z_to_bv 64 (a_SP C)) (Z_to_bv 64 (a_SPA C)) x10
                  (Z_to_bv 64 (- e)) x12 x13 x14 x15 x16 x17 (Z_to_bv 64 (a_FF C)) x19 x20 x21 x22 x23 x24 (Z_to_bv 64 (a_FF C))
                  (Z_to_bv 64 (Z.shiftr (a_FF C) 3 + 2147450880)) x27 x28 x29 x30 x31)
             (a_F C) (Z_to_bv 64 0x95004) (a_fc C) None m' (seg_rom asegs)
    /\ rd_errinvA C m'.

