  Corollary loop_runQ' : forall (Q : machine_state -> Prop) f s sF m1 msvw pc (x6 x10 x11 x12 x13 x14 x15 x16 x17 x19 x23 x30 : word),
    rloop buf msv1 f s = Ok sF ->
    rd_invA C m1 (r_nc s) msvw (Z_to_bv 64 tl) -> CTL msv1 (a_rt0 C) tl s -> POS buf s -> r_bitCount s < 32 ->
    (forall m3 (z6 z11 z14 z15 z17 z19 z23 z30 : word), rd_invA C m3 (r_nc sF) msvw (Z_to_bv 64 tl) -> rd_brk_okA C sF ->
       evtF asegs RNG Q (rd_exitA C sF m3 z6 z11 z14 z15 z17 z19 z23 z30)) ->
    pc = (if r_previous0 s then 0x94c0c else 0x94d88) ->
    x6 = Z_to_bv 64 (r_bitCount s) -> x10 = Z_to_bv 64 (BUF + r_ip s) -> x11 = Z_to_bv 64 (bv_swrap 32 (r_bitStream s)) ->
    x13 = Z_to_bv 64 (r_charnum s) -> x16 = Z_to_bv 64 (r_remaining s) -> x17 = Z_to_bv 64 (r_threshold s) ->
    x23 = Z_to_bv 64 (r_nbBits s) ->
